plan:
{
  "goal": "制定可验证的数据库模式变更部署计划，在45分钟维护窗口内将O、P依次升级，并使旧版A与新版O/P兼容共存；累计服务中断不得超过2分钟，且保留可执行的恢复路径。",
  "assumptions": [
    "本计划仅用于规划，不执行任何操作。具体数据库、模式差异、部署与监测手段均未提供，不能假定具备在线DDL、变更捕获、双写、自动回滚等能力。",
    "数据迁移耗时按题目给定的30分钟计算；迁移是否包含最终追平及一致性校验尚不明确，若不包含，额外耗时必须计入45分钟窗口。",
    "以下时间预算是有条件的上限，不是已确认的能力：模式扩展4分钟、迁移30分钟、O升级及验证3分钟、P升级及验证3分钟、最终验证2分钟、恢复预留3分钟。",
    "窗口外准备和演练仅在另行获准时进行；若不允许，准备耗时也必须计入窗口，不能隐去。",
    "恢复预留3分钟不代表允许中断3分钟。任何恢复过程仍须满足本次窗口累计中断不超过2分钟。",
    "部署目标不是立即删除旧模式。A仍依赖旧模式，因此本次不得删除旧列，也不得实施其他会破坏旧版读写或回滚能力的不可逆变更。"
  ],
  "steps": [
    {
      "id": "S1",
      "action": "在获准的准备阶段明确模式差异、A/O/P读写字段、约束及数据语义，记录当前版本和数据基线。定义中断计时口径、错误率、延迟、数据一致性的通过阈值及负责人；不能通过降低原有服务要求来满足窗口。",
      "depends_on": [],
      "done_when": "兼容性矩阵、验证项目、可观测信号、阈值、中断计时方式及决策责任人均已确认；窗口外准备是否获准已明确。",
      "fallback": "缺少必要信息或可靠观测能力时，不批准实施；若准备必须占用窗口，则重新核算总预算。"
    },
    {
      "id": "S2",
      "action": "设计仅扩展、不收缩的兼容方案：保留A使用的旧列、旧接口及可接受的数据语义，为新版O/P增加所需结构。明确并验证共存期读写规则，包括A写入的数据如何被新版读取、新版写入的数据如何被A及回滚后的旧版读取、并发更新如何避免覆盖或丢失。所需兼容机制必须实际确认可用，不能假定已有。",
      "depends_on": [
        "S1"
      ],
      "done_when": "旧A、新O/P和回滚后的旧O/P均可读取必要数据；所有写入方向、冲突处理和旧字段维护方式都有可验证方案；不存在无法降级表示的新数据。",
      "fallback": "若旧A无法解释新版必需的数据语义，或兼容需要的能力不可用，则停止本次升级，调整O/P版本或拆分发布，不强行共存。"
    },
    {
      "id": "S3",
      "action": "确认迁移及恢复可行性：验证迁移过程中业务写入不会遗漏，迁移能安全停止或完成后保持兼容，重复处理不会损坏数据；确认模式扩展的锁定影响。按可获得的验证条件测量部署、校验和最坏情况下O/P回退及必要数据处理耗时。恢复不得依赖恢复备份而未经验证其时长。",
      "depends_on": [
        "S2"
      ],
      "done_when": "迁移期间并发写入的一致性方案和停止条件已通过验证；扩展不破坏旧服务；最坏恢复路径不超过3分钟且累计中断可控制在2分钟内；所有时间有依据。",
      "fallback": "若迁移需要连续停写30分钟，则违反2分钟中断限制，取消本窗口实施；若无法安全终止、追平或在预算内恢复，也取消实施。"
    },
    {
      "id": "S4",
      "action": "作出上线准入决定并锁定计时表：窗口0—4分钟扩展，4—34分钟迁移，34—37分钟升级验证O，37—40分钟升级验证P，40—42分钟最终验证，42—45分钟仅作恢复预留。所有必要操作和校验必须计入预算，不得把未计入的收尾视为免费。设置早于累计中断120秒的停止阈值，具体提前量须覆盖已验证的恢复耗时。",
      "depends_on": [
        "S3"
      ],
      "done_when": "已确认正常路径不超过42分钟、最坏恢复不超过45分钟，且累计中断不超过120秒；停止阈值具有恢复余量。每个阶段均有明确继续或停止决定。",
      "fallback": "30分钟迁移只留下15分钟用于其他全部工作；上述阶段上限或中断约束只要有一项无法证明，即判定本窗口不可行，另行安排，不以压缩验证或挪用恢复预留补足。"
    },
    {
      "id": "S5",
      "action": "窗口开始后仅实施已验证的模式扩展及必要兼容配置，保持旧A/O/P正常读写；检查锁等待、错误率、延迟及旧版读写结果。不得删除旧列、改变旧字段含义或施加旧版无法满足的约束。",
      "depends_on": [
        "S4"
      ],
      "done_when": "最迟第4分钟完成扩展和旧版冒烟验证，旧服务满足阈值，中断计时和剩余预算允许继续。",
      "fallback": "出现兼容错误、锁影响超阈值或超时即停止向前；旧服务安全时保留无害的新增结构，不为恢复原貌执行危险DDL，按S10处理异常。"
    },
    {
      "id": "S6",
      "action": "在兼容模式下运行30分钟迁移，持续检查业务健康和新旧数据一致性；按已验证方案覆盖迁移期间的新增及修改数据。完成时检查记录覆盖、关键字段映射、约束及并发写入追平情况。",
      "depends_on": [
        "S5"
      ],
      "done_when": "最迟第34分钟迁移和本阶段必要校验完成，无遗漏、丢失或不可解释的差异，旧A/O/P仍能正常读写。",
      "fallback": "迁移异常、未追平或预计无法按时完成时，不升级O/P；按预先验证的安全停止路径保留旧版服务。若停止本身不能满足时间及中断限制，说明准入条件不成立，不应启动本阶段。"
    },
    {
      "id": "S7",
      "action": "仅升级O，保持A和P旧版运行；验证新版O自身读写，以及旧A或旧P写入后新版O读取、新版O写入后旧A或旧P读取的结果，同时检查错误率、延迟和数据一致性。",
      "depends_on": [
        "S6"
      ],
      "done_when": "最迟第37分钟完成O升级及混合版本验证，全部指标符合阈值，保留完整恢复余量。",
      "fallback": "任一验证失败或超时，不升级P；启动S10，优先回退O并保留兼容模式和旧列。"
    },
    {
      "id": "S8",
      "action": "在O验证通过后升级P，保持A旧版运行；验证A旧版与O/P新版的交叉读写、业务关键路径、约束及并发修改，确认新版写入仍能被旧版及回滚版本正确处理。",
      "depends_on": [
        "S7"
      ],
      "done_when": "最迟第40分钟完成P升级及验证，A旧版和O/P新版确实同时运行，所有约定检查通过。",
      "fallback": "P失败或混合版本异常时停止向前，按S10回退受影响服务；不能假定只回退P即可消除所有影响。"
    },
    {
      "id": "S9",
      "action": "在第40—42分钟进行整体复核，记录实际共存区间、版本、数据校验结果、累计中断和剩余恢复时间。第42分钟前决定接受本次部署或启动恢复；不得再增加模式收缩等工作。",
      "depends_on": [
        "S8"
      ],
      "done_when": "最迟第42分钟所有成功阈值通过，旧A与新O/P共存得到验证；若未通过，已作出恢复决定并留下至少已验证的最坏恢复时间。",
      "fallback": "未通过、证据不足或健康状态不稳定均视为未成功，执行S10，不以窗口结束为由接受风险。"
    },
    {
      "id": "S10",
      "action": "本步骤是S5—S9任一阶段触发的条件分支，不必等待S9才执行。停止继续变更，按已验证方案安全停止迁移或隔离异常写入，并依据依赖关系将已升级的P、O恢复到旧版本；保持旧列及必要兼容机制，核对变更期间数据和旧服务健康。监测中断预算，提前决策，禁止等累计中断达到120秒才开始恢复。",
      "depends_on": [
        "S4"
      ],
      "done_when": "触发后在已验证的恢复时限内恢复旧版服务和数据一致性，且不晚于窗口第45分钟；本次累计中断不超过120秒，保留可核查记录。",
      "fallback": "若发生超出已验证恢复能力的故障，立即升级事故处置、保护数据并明确报告限制已被突破或即将突破；不得宣称能够保证时限，也不得删除旧列试图修复。"
    },
    {
      "id": "S11",
      "action": "关闭窗口并报告实际结果：成功、已恢复或事故未恢复。成功时保留旧模式及兼容机制，将旧列删除列为独立后续变更；只有A及其他旧模式依赖均已退出、数据验证完成且不可逆风险另行获批后，才考虑收缩。",
      "depends_on": [
        "S9",
        "S10"
      ],
      "done_when": "已按实际经过的分支记录最终版本、数据状态、窗口耗时和累计中断；未触发的恢复分支标记为不适用；旧列仍保留，后续收缩不计入本次成功。",
      "fallback": "存在未验证项或超时、中断超限时如实标记本次部署未达标，持续事故处置或另行计划，不隐瞒为成功。"
    }
  ],
  "success_criteria": [
    "仅在所有准入条件得到验证后实施；若现有能力不支持时间、中断、兼容或恢复要求，明确判定本窗口不可行。",
    "成功部署时A保持旧版，O和P按顺序完成升级，并在窗口内实际验证三者混合版本共存和双向数据可读写。",
    "迁移结果完整且并发更新不丢失，关键业务、错误率、延迟和一致性检查全部达到预先约定阈值。",
    "正常部署或触发后的恢复均在45分钟内结束，本次累计服务中断不超过2分钟；恢复完成不等同于升级成功。",
    "未删除旧列或实施其他破坏兼容及回滚能力的不可逆变更，恢复路径不依赖未经确认的工具或能力。"
  ]
}

{
  "goal": "制定数据库模式变更的部署计划：在45分钟维护窗口内完成兼容性扩展、30分钟数据迁移以及O、P的顺序更新，同时将累计服务中断控制在2分钟以内。保留旧版A与新版O/P并行运行的能力，并排除本次部署中的旧列删除。",
  "assumptions": [
    "本计划仅描述执行方案，不实际执行数据库变更、迁移或服务部署。",
    "具体数据库类型、表规模、DDL锁行为、部署方式、现有数据同步机制和监控能力均未提供，不能假定在线DDL、双写、变更捕获或自动回滚已经可用。",
    "需先确认旧版A的具体读写行为，以及新旧数据表示是否能无损互换；若无法兼容，不能在本次窗口内强行切换。",
    "数据迁移耗时30分钟按已知约束计入，但该时长是否包括并发写入追平和最终一致性校验尚不明确，必须在准入检查中确认。",
    "45分钟预算暂按模式扩展3分钟、迁移30分钟、迁移验证2分钟、O更新3分钟、P更新3分钟、最终验证2分钟、恢复预留2分钟划分；除迁移外均为待验证上限，而非已知事实。",
    "准备与演练是否允许在维护窗口前完成尚不明确；若准备工作也必须计入45分钟，必须重新计算预算，无法满足时延期。",
    "允许中断按累计受影响时间不超过120秒保守计算；具体受影响请求和计时口径需在部署前确认。"
  ],
  "steps": [
    {
      "id": "S1",
      "action": "梳理A、O、P对现有模式的读写依赖、新模式的变化及回退需求。采用扩展而非破坏性修改：保留旧列及其旧语义，不删除、重命名或直接实施不兼容类型变更。明确A旧版与O/P新版同时运行所需的数据读写兼容规则。",
      "depends_on": [],
      "done_when": "形成读写兼容矩阵，覆盖A旧版、O旧版/新版、P旧版/新版；每种部署中间状态均有明确的数据读写路径，且本次变更不含旧列删除。",
      "fallback": "若新版行为必须依赖破坏性变更，或A的旧版访问无法保持兼容，则判定本次目标不可执行，调整设计或延期。"
    },
    {
      "id": "S2",
      "action": "确定并验证并发写入的一致性方案及迁移的安全停止方式。不能仅依赖新版O/P双写，因为旧版A仍可能写旧列；所有写入来源都必须被覆盖。验证新版写入在回退旧版后仍可读且不丢失，迁移中断或部分完成也不会破坏旧服务。仅采用实际具备且验证过的机制。",
      "depends_on": [
        "S1"
      ],
      "done_when": "A写入、新版O/P读写、迁移并发写入及回退后的数据可见性均通过验证；明确迁移如何停止、重试和避免覆盖较新数据。",
      "fallback": "若没有可用的一致性机制，或需长时间停止写入才能迁移，则当前约束下不可部署。不能以假定存在双写、触发器或变更捕获来绕过问题。"
    },
    {
      "id": "S3",
      "action": "完成部署与恢复准入检查：确认实际可用的发布、验证和恢复手段，测量DDL锁等待、各服务更新时间、迁移及追平时间、故障发现和恢复耗时。预先约定错误率、延迟、数据差异、锁等待和同步积压阈值。核实是否可在不中断服务的情况下迁移，并建立维护窗口及累计中断计时。恢复上限必须包含故障发现、操作及恢复验证。",
      "depends_on": [
        "S2"
      ],
      "done_when": "有可核验依据证明全部正常路径不超过43分钟、预留2分钟足以执行恢复路径，且累计中断不超过120秒；明确各阶段的最晚停止点。准备工作已在窗口外获准完成，或已计入重新核准的45分钟预算。",
      "fallback": "任一耗时、兼容性或恢复条件未经验证即不准入。若恢复需超过2分钟，可以重新分配预算，但必须仍满足总计45分钟和中断120秒；否则延期或申请调整约束。"
    },
    {
      "id": "S4",
      "action": "窗口第0—3分钟仅执行已验证的增量模式扩展，并持续检查A及旧版O/P的读写、锁等待和服务指标。所有原列保留。若执行可能阻塞，应使用已验证的限时或取消方式，不临时采用未经验证的操作。",
      "depends_on": [
        "S3"
      ],
      "done_when": "第3分钟前完成扩展；旧版A/O/P读写正常，无超阈值锁等待或指标异常，累计中断仍在预算内。",
      "fallback": "扩展超时或旧版服务异常时停止后续步骤，按S10恢复；保留无害的新增对象，不为回到原样而冒险删除已有数据。"
    },
    {
      "id": "S5",
      "action": "窗口第3—33分钟执行30分钟数据迁移，同时运行已验证的并发写入一致性方案，监测迁移进度、服务健康及同步积压。迁移期间不暂停旧版A的必要读写；任何短暂停写均须事先验证并计入累计中断。",
      "depends_on": [
        "S4"
      ],
      "done_when": "第33分钟前迁移及所要求的并发写入追平完成，服务保持在约定阈值内；完成状态可通过迁移进度及一致性证据确认。",
      "fallback": "若30分钟不包含追平，或预测无法在阶段截止前完成，停止升级O/P并按S10处理。不得挤占未经重新验证的验证或恢复预算。"
    },
    {
      "id": "S6",
      "action": "窗口第33—35分钟验证迁移结果与读写兼容性。依据预先制定的校验规则核对关键数据完整性、新旧表示一致性及迁移遗漏，并验证A继续写入后新表示仍及时可用。校验范围及其无法覆盖的风险须明确记录。",
      "depends_on": [
        "S5"
      ],
      "done_when": "第35分钟前通过既定一致性阈值和关键业务读写验证；没有未解释的数据差异或超限积压，且剩余时间足以完成后续部署、验证和恢复。",
      "fallback": "校验不通过、证据不足或超时则禁止升级O/P，按S10处理；不得把迁移完成等同于迁移正确。"
    },
